-- Demo fulfilled orders for apex_order. Pass the demo customer's id as the psql variable customer_id.
-- Safe to re-run: the same order and line ids update in place.
BEGIN;
ON CONFLICT (id) DO UPDATE SET
  status = EXCLUDED.status,
  total_cents = EXCLUDED.total_cents,
  address_snapshot = EXCLUDED.address_snapshot,
  created_at = EXCLUDED.created_at;

ON CONFLICT (id) DO UPDATE SET
  product_name = EXCLUDED.product_name,
  unit_price_cents = EXCLUDED.unit_price_cents,
  quantity = EXCLUDED.quantity,
  line_total_cents = EXCLUDED.line_total_cents,
  sku = EXCLUDED.sku,
  category_code = EXCLUDED.category_code;
COMMIT;
